import type { Product } from '@/types'

const daysAgo = (n: number) => {
  const d = new Date()
  d.setDate(d.getDate() - n)
  return d.toISOString()
}

interface Seed {
  name: string
  description: string
  details: string[]
  price: number
  originalPrice?: number
  category: Product['category']
  brand: string
  images: string[]
  colors: string[]
  sizes: Product['sizes']
  rating: number
  reviewCount: number
  stock: number
  isNew?: boolean
  isBestSeller?: boolean
  discount?: number
  material?: string
  tags: string[]
  soldCount: number
  createdDaysAgo: number
}

let nextId = 1
const build = (seed: Seed): Product => ({
  id: nextId++,
  name: seed.name,
  description: seed.description,
  details: seed.details,
  price: seed.price,
  originalPrice: seed.originalPrice,
  category: seed.category,
  brand: seed.brand,
  images: seed.images,
  colors: seed.colors,
  sizes: seed.sizes,
  rating: seed.rating,
  reviewCount: seed.reviewCount,
  stock: seed.stock,
  isNew: seed.isNew ?? false,
  isBestSeller: seed.isBestSeller ?? false,
  discount: seed.discount,
  material: seed.material,
  tags: seed.tags,
  soldCount: seed.soldCount,
  createdAt: daysAgo(seed.createdDaysAgo),
})

